def build(run_id):
    run = ROOT / 'runs' / run_id
    cases = read(ROOT / 'data/cases.json')
    data = {key: read(run / (key + '.json')) for key in ('manifest', 'summary', 'management')}
    data.update(cases=cases, rubric=read(ROOT/'data/rubric.json'),
                sources=read(ROOT/'data/sources.json'), knowledge=read(ROOT/'data/knowledge.json'), results={})
    for arm in ('baseline', 'skill'):
        data['results'][arm] = {}
        for case in cases:
            path = run / arm / case['case_id']
            item = {key: read(path/(key+'.json')) for key in ('input', 'output', 'execution', 'grade')}
            item['host_trace'] = read(path/'host-trace.json')
            item['events'] = [json.loads(s) for s in (path/'events.public.jsonl').read_text().splitlines() if s]
            data['results'][arm][case['case_id']] = item
    target = REPO / 'docs/demo/index.html'
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(TEMPLATE.replace('__DEMO_DATA__', json.dumps(data, ensure_ascii=False).replace('<', '\\u003c')))
    print(target)


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('run_id')
    build(parser.parse_args().run_id)
